const slides=[...document.querySelectorAll('.hero-slide')],dots=[...document.querySelectorAll('.slider-dot')];let activeSlide=0,sliderTimer;function showSlide(index){if(!slides.length)return;activeSlide=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('is-active',i===activeSlide));dots.forEach((dot,i)=>{dot.classList.toggle('is-active',i===activeSlide);dot.setAttribute('aria-current',i===activeSlide?'true':'false')})}function startSlider(){clearInterval(sliderTimer);sliderTimer=setInterval(()=>showSlide(activeSlide+1),6500)}dots.forEach((dot,i)=>dot.addEventListener('click',()=>{showSlide(i);startSlider()}));showSlide(0);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)startSlider();
const brandTrack=document.querySelector('.brand-track');if(brandTrack){const original=brandTrack.innerHTML;brandTrack.innerHTML='<div class="brand-group">'+original+'</div><div class="brand-group" aria-hidden="true">'+original+'</div><div class="brand-group" aria-hidden="true">'+original+'</div>';}
document.querySelectorAll('.section-heading,.service-card,.process-visual,.process-copy,.benefit-grid article,.local-copy,.local-art,.faq-intro,.faq-list').forEach(el=>el.classList.add('reveal'));const revealObserver=new IntersectionObserver((entries)=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));</script>
